#include "leds.h"
#include "config.h"
#include "hardware/clocks.h"
#include "hardware/pio.h"
#include "hardware/pio_instructions.h"

// The LED signal is generated by a PIO state machine, so the pulse timing
// doesn't depend on what the CPU is doing (flash fetches, interrupts, ...).
// The CPU just hands it 24 bits per LED.

// With ears pointing down: LED order:
// 0: front_top_left
// 1: front_middle_left
// 2: front_bottom_left
// 3: front_bottom_right
// 4: front_top_right
// 5: back_top_left
// 6: back_bottom_left
// 7: back_top_right
// 8: back_bottom_right

static uint32_t led_buffer[LED_COUNT]; // stored as GRB, the order WS2812 expects
char lit_leds[LED_COUNT]; // declared in leds.h

// --- PIO program ---
// Each bit is three phases, T1 + T2 + T3 PIO cycles long:
//   0 bit: high T1,      low T2 + T3
//   1 bit: high T1 + T2, low T3
// So T1 = 0-bit high time, T1 + T2 = 1-bit high time, T3 = low time.
// Same program as the Pico SDK's ws2812 example, written in code instead of
// a .pio file so the T values can be changed at runtime:
//
//   bitloop: out x, 1       side 0 [T3 - 1]  ; low, and take the next bit
//            jmp !x do_zero side 1 [T1 - 1]  ; high
//   do_one:  jmp bitloop    side 1 [T2 - 1]  ; 1: stay high
//   do_zero: nop            side 0 [T2 - 1]  ; 0: go low
//
// "side" sets the LED pin with each instruction; [n] waits n extra cycles.
// With 1 side-set bit, 4 bits are left for the wait, so each phase is
// 1..16 cycles. The PIO clock is slowed down until the longest phase fits.

#define LED_PIO      pio0
#define PHASE_MAX    16 // most PIO cycles one phase can last

static int led_sm = -1;          // state machine, claimed in leds_init
static uint led_offset;          // where our program sits in PIO memory
static bool led_program_loaded = false;
static uint16_t led_instructions[4];
static const pio_program_t led_program = {
    .instructions = led_instructions,
    .length = 4,
    .origin = -1, // load anywhere
};
static uint32_t led_bit_ns; // length of one bit, for the latch wait

static uint32_t ns_to_sys_cycles(uint32_t ns) {
    return (uint32_t)((uint64_t)clock_get_hz(clk_sys) * ns / 1000000000u);
}

// Phase length in PIO cycles, rounded, kept within 1..PHASE_MAX
static uint phase_cycles(uint32_t ns, uint32_t div) {
    uint32_t c = (ns_to_sys_cycles(ns) + div / 2) / div;
    if (c < 1) c = 1;
    if (c > PHASE_MAX) c = PHASE_MAX;
    return c;
}

void leds_set_timing(uint32_t t0h_ns, uint32_t t1h_ns, uint32_t tlow_ns) {
    if (led_sm < 0) return; // leds_init not called yet

    uint32_t t1_ns = t0h_ns;
    uint32_t t2_ns = t1h_ns > t0h_ns ? t1h_ns - t0h_ns : 1;
    uint32_t t3_ns = tlow_ns;

    // Slow the PIO clock (whole-number divider, no jitter) until the
    // longest phase fits in PHASE_MAX cycles
    uint32_t longest = t1_ns;
    if (t2_ns > longest) longest = t2_ns;
    if (t3_ns > longest) longest = t3_ns;
    uint32_t div = (ns_to_sys_cycles(longest) + PHASE_MAX - 1) / PHASE_MAX;
    if (div < 1) div = 1;

    uint t1 = phase_cycles(t1_ns, div);
    uint t2 = phase_cycles(t2_ns, div);
    uint t3 = phase_cycles(t3_ns, div);
    led_bit_ns = (uint32_t)((uint64_t)(t1 + t2 + t3) * div * 1000000000u / clock_get_hz(clk_sys));

    // Stop and unload the old program before loading the new one
    pio_sm_set_enabled(LED_PIO, led_sm, false);
    if (led_program_loaded) pio_remove_program(LED_PIO, &led_program, led_offset);

    // Jump targets are relative to the program start; pio_add_program fixes
    // them up for wherever it gets loaded.
    led_instructions[0] = pio_encode_out(pio_x, 1)  | pio_encode_sideset(1, 0) | pio_encode_delay(t3 - 1);
    led_instructions[1] = pio_encode_jmp_not_x(3)   | pio_encode_sideset(1, 1) | pio_encode_delay(t1 - 1);
    led_instructions[2] = pio_encode_jmp(0)         | pio_encode_sideset(1, 1) | pio_encode_delay(t2 - 1);
    led_instructions[3] = pio_encode_nop()          | pio_encode_sideset(1, 0) | pio_encode_delay(t2 - 1);
    led_offset = pio_add_program(LED_PIO, &led_program);
    led_program_loaded = true;

    pio_sm_config c = pio_get_default_sm_config();
    sm_config_set_wrap(&c, led_offset, led_offset + 3);
    sm_config_set_sideset(&c, 1, false, false); // 1 side-set bit, always used
    sm_config_set_sideset_pins(&c, PIN_LEDS);
    sm_config_set_out_shift(&c, false, true, 24); // MSB first, auto-refill every 24 bits
    sm_config_set_fifo_join(&c, PIO_FIFO_JOIN_TX); // 8-deep send queue
    sm_config_set_clkdiv_int_frac8(&c, div, 0);

    pio_sm_init(LED_PIO, led_sm, led_offset, &c);
    pio_sm_set_enabled(LED_PIO, led_sm, true);
}

void leds_init() {
    // Hand the pin to the PIO and make it an output, idling low
    pio_gpio_init(LED_PIO, PIN_LEDS);
    led_sm = pio_claim_unused_sm(LED_PIO, true);
    pio_sm_set_pins_with_mask(LED_PIO, led_sm, 0, 1u << PIN_LEDS);
    pio_sm_set_consecutive_pindirs(LED_PIO, led_sm, PIN_LEDS, 1, true);

    leds_set_timing(LED_T0H_NS, LED_T1H_NS, LED_TLOW_NS);

    leds_set_all(0, 0, 0);
    leds_show();
}

void leds_set(int index, uint8_t r, uint8_t g, uint8_t b) {
    if (index < 0 || index >= LED_COUNT) return;
    led_buffer[index] = ((uint32_t)g << 16) | ((uint32_t)r << 8) | b;
    lit_leds[index] = (r || g || b);
}

void leds_set_all(uint8_t r, uint8_t g, uint8_t b) {
    for (int i = 0; i < LED_COUNT; i++) {
        leds_set(i, r, g, b);
    }
}

void leds_show() {
    // The PIO sends the top 24 bits of each word, so shift the GRB value up.
    // put_blocking only waits if the 8-entry queue is full.
    for (int i = 0; i < LED_COUNT; i++) {
        pio_sm_put_blocking(LED_PIO, led_sm, led_buffer[i] << 8);
    }

    // WS2812 latches the colors once the line stays low long enough. Wait for
    // the queue to empty, then for the last LED's 24 bits plus the latch time,
    // so a quick second leds_show can't run into this one.
    while (!pio_sm_is_tx_fifo_empty(LED_PIO, led_sm)) tight_loop_contents();
    sleep_us(24 * led_bit_ns / 1000 + 300);
}
